// Fixed原owner边界的完整字段回归；fixture只用于验证冷编码，不冒真实接受证据。
#include "resident/domains/growth/growth_fixed_service_codec.hpp"
#include "resident/domains/actor_foundation/actor_foundation_codec.hpp"
#include <algorithm>
#include <cstdlib>
#include <new>
#include <iostream>
#include <limits>
#include <stdexcept>
using namespace hanmo::resident;
// 测试专用一次分配故障；生产codec没有测试开关或替代路径。
static long allocation_failure_after=-1;
static void (*volatile allocation_release)(void*)=std::free;
void* operator new(std::size_t size){if(allocation_failure_after==0){allocation_failure_after=-1;throw std::bad_alloc();}if(allocation_failure_after>0)--allocation_failure_after;if(auto* p=std::malloc(size?size:1))return p;throw std::bad_alloc();}
void* operator new[](std::size_t size){return ::operator new(size);}
void operator delete(void* p)noexcept{allocation_release(p);}
void operator delete[](void* p)noexcept{allocation_release(p);}
void operator delete(void* p,std::size_t)noexcept{allocation_release(p);}
void operator delete[](void* p,std::size_t)noexcept{allocation_release(p);}
namespace {
// 断言始终开启，避免发行配置的NDEBUG吞掉拒绝检查。
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
// 数值fixture仍由生产精确数值叶构造。
WorldMoment moment(){auto f=normalize_fraction("9007199254740993","9007199254740995");check(f.ok,"fixture fraction");return {42,f.value};}
// 锁内目录字段不是虚构事实；保留完整目录身份与实际selector。
LifeCatalogFieldRef catalog_ref(const char* selector){CatalogIdentity c{"content","1","digest","rules","schema",StableId{"pack"},{{"growth","36"}},"artifact"};return {c,"scenario","entity",selector};}
// capability九槽必须经同一完整编码，不能截成一个allowed布尔值。
FrozenFacilityCapabilityInputs frame(){FrozenFacilityCapabilityInputs f;f.actor_id="actor";f.purpose_ref={"rest",1,"digest"};f.captured_at=moment();f.condition_head_snapshot={"actor",0,{"seed"},{}};f.body_scalars={true,100,40,0,{}};f.selected_rule_refs={{"rule",1,"digest"}};f.result={true,10000,{}, {"rule",1,"digest"},moment()};return f;}
// started与terminal只改变原边界中真实存在的分支，全部空槽仍需编码。
LifeFixedServiceBoundary sample(bool terminal=false){LifeFixedServiceBoundary b;b.boundary_id=terminal?"end":"start";b.action_ref="action";b.action_kind="service";b.owner_ref={1,"activity",0};b.occurred_at=moment();LifeActualCommand cmd;cmd.actor_id="actor";cmd.command_binding={"start_service",std::numeric_limits<Integer>::max(),"result"};cmd.route_basis=LifePlayerActorRoute{catalog_ref("scenario.player_actor")};cmd.accepted_business_ref=LifeOwnedFieldRef{{"growth","life_activity","activity"},"terms"};b.cause=cmd;LifeFixedActorInputs a;a.actor_id="actor";a.role="recipient";a.capability_frames={frame()};a.origin_actor_key="actor";a.location_snapshot=SettlementLocation{"settlement","place"};a.actual_location_source_refs={ScenarioOriginRef{"digest","scenario","actor",0}};a.participation_source_refs={SourceRef{"growth","life_activity","activity"}};a.occupation_source_refs={LifeOwnedFieldRef{{"growth","life_activity","activity"},"actor_id"}};b.input_snapshot.actors={a};b.input_snapshot.locked_rule_refs={catalog_ref("activities.rest")};b.input_snapshot.accepted_permission_refs={{"service_terms",LifeOwnedFieldRef{{"growth","life_activity","activity"},"terms"},1},{"provider_role",catalog_ref("role"),1}};b.input_snapshot.resource_basis_refs={{LifeResourceBasisRef::Purpose::fee,LifeOwnedFieldRef{{"growth","life_activity","activity"},"cost_paid"},1},{LifeResourceBasisRef::Purpose::wage_reservation,LifeOwnedFieldRef{{"growth","life_activity","activity"},"terms.wage"},1}};auto& s=b.input_snapshot.specific.life_activity;s.activity_id="activity";s.service_role_ref=catalog_ref("roles.provider");s.activity_ref=catalog_ref("activities.rest");if(terminal){b.boundary_ordinal=1;b.previous_boundary_ref="start";b.kind=LifeFixedBoundaryKind::completed;LifeOriginalTerminalApplication t;t.trigger=LifeFixedCompletionGate{"action",catalog_ref("activities.rest.duration"),{}};LifeFixedOutcomeRef outcome;outcome.id="activity";t.actual_result_refs={outcome};b.original_outcome_ref=outcome;b.cause=t;}return b;}
// 仅修改测试自有BoundaryValue，损坏输入不能污染任何真实候选。
BoundaryValue& field(BoundaryValue& v,const char* key){auto* p=v.find(key);check(p!=nullptr,"fixture field");return *p;}
// JSON→typed→binary→typed→JSON须逐值和字段序相同；重复保存不增加边界。
void roundtrip(){for(bool terminal:{false,true}){const auto s=sample(terminal);auto j=encode_growth_fixed_service_boundary(s);check(j.ok,"encode boundary");auto d=decode_growth_fixed_service_boundary(j.value);check(d.ok,"decode boundary");auto bytes=encode_growth_fixed_service_boundary_checkpoint(d.value);check(bytes.ok,"encode checkpoint");auto restored=decode_growth_fixed_service_boundary_checkpoint(bytes.value);check(restored.ok,"decode checkpoint");auto again=encode_growth_fixed_service_boundary(restored.value);check(again.ok&&compare_boundary(j.value,again.value).exact(),"paired fields exact");auto same=encode_growth_fixed_service_boundary_checkpoint(restored.value);check(same.ok&&same.value==bytes.value,"save no new source");auto& actor=std::get<BoundaryValue::Array>(field(field(j.value,"input_snapshot"),"actors").data).front();check(std::get<BoundaryValue::Dict>(actor.data).size()==13,"actor all thirteen slots");check(std::get<BoundaryValue::Dict>(std::get<BoundaryValue::Array>(field(actor,"capability_frames").data).front().data).size()==9,"capability all nine slots");check(field(field(actor,"location_snapshot"),"kind").as<StableId>()&&*field(field(actor,"location_snapshot"),"kind").as<StableId>()=="Settlement","original location JSON shape");}}
// 必填、null、有限tag与规范分数的破坏均须冷拒，不能回填默认值。
void json_rejections(){auto good=encode_growth_fixed_service_boundary(sample());check(good.ok,"JSON fixture");auto reject=[](const BoundaryValue& v){check(!decode_growth_fixed_service_boundary(v).ok,"bad JSON rejected");};auto v=good.value;std::get<BoundaryValue::Dict>(v.data).pop_back();reject(v);v=good.value;std::get<BoundaryValue::Dict>(v.data).push_back(std::get<BoundaryValue::Dict>(v.data).front());reject(v);v=good.value;std::get<BoundaryValue::Dict>(v.data).emplace_back("extra",Integer{0});reject(v);v=good.value;field(v,"previous_boundary_ref")=BoundaryValue{Integer{0}};reject(v);v=good.value;field(v,"boundary_ordinal")=BoundaryValue{0.5};reject(v);v=good.value;field(v,"source_schema")=BoundaryValue{Integer{2}};reject(v);v=good.value;field(v,"kind")=BoundaryValue{Integer{6}};reject(v);v=good.value;field(field(v,"owner_ref"),"tag")=BoundaryValue{Integer{8}};reject(v);v=good.value;field(field(v,"owner_ref"),"tag")=BoundaryValue{Integer{0}};reject(v);v=good.value;field(field(v,"cause"),"tag")=BoundaryValue{Integer{1}};reject(v);v=good.value;field(field(field(v,"occurred_at"),"sub_half_day"),"numerator")="02";reject(v);v=good.value;field(field(field(v,"occurred_at"),"sub_half_day"),"numerator")="2";field(field(field(v,"occurred_at"),"sub_half_day"),"denominator")="4";reject(v);v=good.value;field(field(field(v,"occurred_at"),"sub_half_day"),"denominator")="0";reject(v);v=good.value;auto& actor=std::get<BoundaryValue::Array>(field(field(v,"input_snapshot"),"actors").data).front();field(actor,"age_view")=BoundaryValue{BoundaryValue::Dict{}};reject(v);v=good.value;auto& actor2=std::get<BoundaryValue::Array>(field(field(v,"input_snapshot"),"actors").data).front();std::get<BoundaryValue::Array>(field(actor2,"skill_qualification_views").data).push_back(BoundaryValue{BoundaryValue::Dict{}});reject(v);v=good.value;auto& actor3=std::get<BoundaryValue::Array>(field(field(v,"input_snapshot"),"actors").data).front();auto& f=std::get<BoundaryValue::Array>(field(actor3,"capability_frames").data).front();std::get<BoundaryValue::Dict>(f.data).erase(std::get<BoundaryValue::Dict>(f.data).begin()+1);reject(v);check(!parse_boundary_json("{\"n\":9223372036854775808}").ok,"integer overflow parser");check(!parse_boundary_json("{\"n\":0} trailing").ok,"JSON trailing parser");}
// 未实现非空槽以及未接有限kind双向拒绝，typed调用不能绕过JSON的严格检查。
void unsupported(){auto check_unsupported=[](const LifeFixedServiceBoundary& v){auto j=encode_growth_fixed_service_boundary(v);check(!j.ok&&j.error.kind==ErrorKind::unsupported_capability,"unsupported JSON classification");auto b=encode_growth_fixed_service_boundary_checkpoint(v);check(!b.ok&&b.error.kind==ErrorKind::unsupported_capability,"unsupported binary classification");};auto s=sample();s.input_snapshot.actors.front().effective_attribute_inputs.emplace_back();check_unsupported(s);s=sample();s.input_snapshot.specific.life_activity.recovery_service_ref=SourceRef{"growth","recovery","r"};check_unsupported(s);s=sample();s.cause=LifeAcceptedExecution{};check_unsupported(s);s=sample();s.input_snapshot.specific.kind=2;check_unsupported(s);s=sample();s.input_snapshot.actors.front().location_snapshot=WildernessLocation{};check_unsupported(s);s=sample();s.input_snapshot.facility_use_refs.emplace_back();check_unsupported(s);s=sample();s.input_snapshot.resource_basis_refs.front().purpose=LifeResourceBasisRef::Purpose::food;check_unsupported(s);s=sample(true);std::get<LifeOriginalTerminalApplication>(s.cause).trigger=LifeOriginalResultTrigger{};check_unsupported(s);}
// 每个截断和尾随均拒绝；公开嵌入visitor失败后保留调用方完整原值。
void binary_rejections(){auto b=encode_growth_fixed_service_boundary_checkpoint(sample());check(b.ok,"binary fixture");for(std::size_t n=0;n<b.value.size();++n){CodecVisitor::Buffer cut(b.value.begin(),b.value.begin()+n);check(!decode_growth_fixed_service_boundary_checkpoint(cut).ok,"binary truncation rejected");}auto tail=b.value;tail.push_back(0);check(!decode_growth_fixed_service_boundary_checkpoint(tail).ok,"binary tail rejected");auto original=sample(true);auto prior=encode_growth_fixed_service_boundary(original);b.value.pop_back();CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(b.value));check(!visit_growth_fixed_service_boundary(reader,original).ok,"embedded truncation rejected");auto after=encode_growth_fixed_service_boundary(original);check(prior.ok&&after.ok&&compare_boundary(prior.value,after.value).exact(),"embedded fail keeps candidate");}
// K3公开frame访客与本嵌入字段必须逐字节一致，防止同名九槽出现第二种布局。
void capability_pairing(){auto s=sample();auto bytes=encode_growth_fixed_service_boundary_checkpoint(s);check(bytes.ok,"capability boundary fixture");auto f=frame();CodecVisitor::Buffer expected;CodecVisitor c(expected);check(visit_frozen_rest_capability_inputs(c,f).ok&&c.finish().ok,"K3 public frame");auto first=std::search(bytes.value.begin(),bytes.value.end(),expected.begin(),expected.end());check(first!=bytes.value.end(),"complete K3 frame bytes embedded");check(std::search(first+1,bytes.value.end(),expected.begin(),expected.end())==bytes.value.end(),"one complete frame only");}
// 所有公开入口分配失败均返internal；尤其嵌入reader不得在发布时半改原目标。
void allocation_failures(){const auto s=sample();auto j=encode_growth_fixed_service_boundary(s);auto b=encode_growth_fixed_service_boundary_checkpoint(s);check(j.ok&&b.ok,"OOM fixtures");for(long fail=0;fail<96;++fail){allocation_failure_after=fail;auto ej=encode_growth_fixed_service_boundary(s);allocation_failure_after=-1;check(ej.ok||ej.error.kind==ErrorKind::internal,"JSON write OOM internal");allocation_failure_after=fail;auto dj=decode_growth_fixed_service_boundary(j.value);allocation_failure_after=-1;check(dj.ok||dj.error.kind==ErrorKind::internal,"JSON read OOM internal");allocation_failure_after=fail;auto eb=encode_growth_fixed_service_boundary_checkpoint(s);allocation_failure_after=-1;check(eb.ok||eb.error.kind==ErrorKind::internal,"binary write OOM internal");allocation_failure_after=fail;auto db=decode_growth_fixed_service_boundary_checkpoint(b.value);allocation_failure_after=-1;check(db.ok||db.error.kind==ErrorKind::internal,"binary read OOM internal");auto target=sample(true);auto before=encode_growth_fixed_service_boundary(target);CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(b.value));allocation_failure_after=fail;auto status=visit_growth_fixed_service_boundary(reader,target);allocation_failure_after=-1;if(!status.ok){check(status.error.kind==ErrorKind::internal,"embedded OOM internal");auto after=encode_growth_fixed_service_boundary(target);check(before.ok&&after.ok&&compare_boundary(before.value,after.value).exact(),"embedded OOM keeps target");}}}

}
int main(){try{roundtrip();json_rejections();unsupported();binary_rejections();capability_pairing();allocation_failures();std::cout<<"growth fixed service codec checks passed\n";return 0;}catch(const std::exception& e){allocation_failure_after=-1;std::cerr<<e.what()<<'\n';return 1;}}
